class AnswerCache:
    def __init__(self):
        self.values = {}

    def answer(self, project, model, prompt, generate):
        key = prompt
        if key not in self.values:
            self.values[key] = generate()
        return self.values[key]

record Edge { source: Text target: Text }
record ReachRequest { start: Text goal: Text edges: Edge[] rounds: Number }
record ReachResult { found: Bool }

fn reachable(request: ReachRequest) -> Bool {
  var frontier: Text[] = [request.start]
  var seen: Text[] = []
  var round = 0
  while not frontier.is_empty() and round < request.rounds {
    var next: Text[] = []
    for node in frontier {
      if seen.contains(node) { return false }
      if node == request.goal { return true }
      seen = seen.append(node)
      for edge in request.edges {
        if edge.source == node { next = next.append(edge.target) }
      }
    }
    frontier = next
    round += 1
  }
  return false
}

fn reach_result(request: ReachRequest) -> ReachResult {
  return {found: reachable(request)}
}

workflow main(request: ReachRequest) -> ReachResult {
  result = reach_result(request)
}
